-- Two retired players still own their original unconsumed paid entries in an
-- undealt Spin. No hand exists, so no hand or original-hand receipt is invented.
-- The exact entry/debit/ledger/entitlement and old chair/roster prove ownership.
-- The platform's ordinary assignment owner creates each successor occupancy;
-- closed profiles and retirement claims remain closed. No wallet is debited,
-- credited, minted or rewritten. All effects belong to this one transaction.
BEGIN;
SET LOCAL lock_timeout='500ms';
SET LOCAL statement_timeout='10s';
CREATE TABLE smarter_private.retirement_undealt_paid_entry_qualification (
 tournament_id uuid PRIMARY KEY, expected jsonb NOT NULL,
 CHECK(jsonb_array_length(expected->'rows')=3));
ALTER TABLE smarter_private.retirement_undealt_paid_entry_qualification OWNER TO postgres;
REVOKE ALL ON smarter_private.retirement_undealt_paid_entry_qualification FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE smarter_private.retirement_undealt_paid_entry_restorations (
 tournament_id uuid PRIMARY KEY, qualification_hash text NOT NULL,
 transaction_id bigint NOT NULL, instance_id text NOT NULL, lease_generation uuid NOT NULL,
 native_results jsonb NOT NULL, restored_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE smarter_private.retirement_undealt_paid_entry_restorations OWNER TO postgres;
REVOKE ALL ON smarter_private.retirement_undealt_paid_entry_restorations FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION smarter_private.retirement_undealt_paid_entry_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $immutable$ BEGIN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_RECEIPT_IMMUTABLE' USING ERRCODE='55000';END;$immutable$;
ALTER FUNCTION smarter_private.retirement_undealt_paid_entry_immutable() OWNER TO postgres;
REVOKE ALL ON FUNCTION smarter_private.retirement_undealt_paid_entry_immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER qualification_immutable BEFORE UPDATE OR DELETE ON smarter_private.retirement_undealt_paid_entry_qualification FOR EACH ROW EXECUTE FUNCTION smarter_private.retirement_undealt_paid_entry_immutable();
CREATE TRIGGER restoration_immutable BEFORE UPDATE OR DELETE ON smarter_private.retirement_undealt_paid_entry_restorations FOR EACH ROW EXECUTE FUNCTION smarter_private.retirement_undealt_paid_entry_immutable();
