CREATE FUNCTION smarter_private.continue_retired_undealt_paid_entry(p_tournament_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public,smarter_private AS $function$
DECLARE v jsonb; e jsonb; got jsonb; lease public.engine_tournament_leases;
 spin_before jsonb; spin_after jsonb; gate jsonb; result jsonb; results jsonb:='[]'; restored integer:=0; old_data_actor text; old_data_generation text;
BEGIN
 IF session_user<>'postgres' OR auth.role() IS NOT NULL THEN
  RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_CALLER_REFUSED' USING ERRCODE='42501';
 END IF;
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id,NULL);
 SELECT expected INTO v FROM smarter_private.retirement_undealt_paid_entry_qualification
 WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NOT_QUALIFIED' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations WHERE tournament_id=p_tournament_id) THEN
  IF NOT EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations r WHERE r.tournament_id=p_tournament_id AND r.qualification_hash=md5(v::text)) THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_REPLAY_CHANGED' USING ERRCODE='55000';END IF;
  RETURN jsonb_build_object('ok',true,'replayed',true);
 END IF;
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FROZEN' USING ERRCODE='55000';END IF;
 -- Canonical seat acquisition order: every cap/mission before launch/event/chair rows.
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 PERFORM public.fn_ca_lock_mtt_admission_contract();
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||(e->'roster'->>'user_id'),0));
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  PERFORM public.fn_lock_daily_mission_user((e->'roster'->>'user_id')::uuid);
 END LOOP;
 gate:=public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id,(v->'table'->>'id')::uuid,NULL);
 IF gate->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ADMISSION_REFUSED' USING ERRCODE='55000';END IF;
 SELECT * INTO lease FROM public.engine_tournament_leases WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF NOT FOUND OR lease.protocol_version IS DISTINCT FROM 2 OR lease.lease_generation IS NULL OR nullif(lease.instance_id,'') IS NULL OR lease.heartbeat_at IS NULL OR lease.heartbeat_at<clock_timestamp()-interval '30 seconds'
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LEASE_REFUSED' USING ERRCODE='55000';END IF;
 SELECT to_jsonb(t) INTO got FROM public.tournaments t WHERE id=p_tournament_id FOR UPDATE;
 IF (got @> (v->'event')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_EVENT_CHANGED' USING ERRCODE='55000';END IF;
 SELECT to_jsonb(t) INTO got FROM public.tables t WHERE id=(v->'table'->>'id')::uuid FOR UPDATE;
 IF (got @> (v->'table')) IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM smarter_private.hand_submissions s WHERE s.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits h WHERE h.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id AND o.state IN ('park_requested','begun'))
 OR EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.tournament_payouts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.tournament_cancellation_receipts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_private_state r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>3
 OR (SELECT count(*) FROM public.table_seats WHERE table_id=(v->'table'->>'id')::uuid)<>3
 OR (SELECT count(*) FROM public.tournament_participant_funding_receipts WHERE tournament_id=p_tournament_id)<>3
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LATER_OBLIGATION' USING ERRCODE='55000';END IF;
 SELECT jsonb_build_object('reserve',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.spin_reserve_ledger r WHERE tournament_id=p_tournament_id),'journal',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE tournament_id=p_tournament_id AND category='spin_entry'),'draw',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.launch_id) FROM public.spin_draw_receipts d WHERE tournament_id=p_tournament_id)) INTO spin_before;
 IF spin_before IS DISTINCT FROM v->'spin' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_SPIN_RECEIPT_CHANGED' USING ERRCODE='55000';END IF;
 -- Lock and verify the complete original records before the first changed row.
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  SELECT to_jsonb(r)-'username' INTO got FROM public.tournament_players r WHERE id=(e->'roster'->>'id')::uuid FOR UPDATE;
  IF got IS DISTINCT FROM e->'roster' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ROSTER_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(s)-'updated_at' INTO got FROM public.table_seats s WHERE id=(e->'seat'->>'id')::uuid FOR UPDATE;
  IF (got @> (e->'seat')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_CHAIR_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(f) INTO got FROM public.tournament_participant_funding_receipts f WHERE id=(e->'funding'->>'id')::uuid;
  IF got IS DISTINCT FROM e->'funding' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FUNDING_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(l) INTO got FROM public.chip_ledger l WHERE id=(e->'funding'->>'ledger_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'ledger_snapshot' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LEDGER_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(w) INTO got FROM public.wallet_transactions w WHERE id=(e->'funding'->>'wallet_transaction_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'wallet_snapshot' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_DEBIT_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(x) INTO got FROM public.tournament_refund_entitlements x WHERE id=(e->'funding'->>'entitlement_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'entitlement_snapshot'
  OR EXISTS(SELECT 1 FROM public.tournament_refund_tranches x WHERE x.entitlement_id=(e->'funding'->>'entitlement_id')::uuid)
  OR EXISTS(SELECT 1 FROM public.tournament_tickets x WHERE x.source_refund_entitlement_id=(e->'funding'->>'entitlement_id')::uuid)
  THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ENTITLEMENT_CONSUMED' USING ERRCODE='55000';END IF;
  IF e->'retirement'<>'null'::jsonb THEN
   IF NOT EXISTS(SELECT 1 FROM smarter_private.patterned_identity_retirements r
    JOIN public.profiles p ON p.id=r.old_id
    WHERE r.old_id=(e->'retirement'->>'user_id')::uuid AND r.cohort=e->'retirement'->>'cohort'
     AND r.benched_at=(e->'retirement'->>'benched_at')::timestamptz
     AND r.retired_at=(e->'retirement'->>'retired_at')::timestamptz
     AND r.replacement_horse_id IS NULL
     AND p.horse_status='disabled' AND p.status='deleted') THEN
    RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_RETIREMENT_CHANGED' USING ERRCODE='55000';END IF;
  END IF;
 END LOOP;
 old_data_actor:=current_setting('app.smarter_data_actor',true);
 old_data_generation:=current_setting('app.smarter_data_generation',true);
 PERFORM set_config('app.smarter_data_actor',lease.instance_id,true);
 PERFORM set_config('app.smarter_data_generation',lease.lease_generation::text,true);
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  IF e->'retirement'='null'::jsonb THEN CONTINUE;END IF;
  UPDATE public.tournament_players SET status='playing',eliminated_at=NULL
  WHERE id=(e->'roster'->>'id')::uuid;
  result:=public.fn_assign_tournament_player_seat_atomic(p_tournament_id,(e->'roster'->>'user_id')::uuid,
    (v->'table'->>'id')::uuid,(e->'roster'->>'seat_number')::integer);
  IF result->>'ok' IS DISTINCT FROM 'true' OR (result->>'stack')::numeric<>1000
   OR (result->>'seat_id')::uuid<>(e->'seat'->>'id')::uuid THEN
   RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NATIVE_ASSIGNMENT_REFUSED: %',result USING ERRCODE='P0404';END IF;
  results:=results||jsonb_build_array(result);restored:=restored+1;
 END LOOP;
 PERFORM set_config('app.smarter_data_actor',coalesce(old_data_actor,''),true);
 PERFORM set_config('app.smarter_data_generation',coalesce(old_data_generation,''),true);
 IF restored<>2 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id AND status='playing' AND chips=1000)<>3
 OR (SELECT count(*) FROM public.table_seats WHERE table_id=(v->'table'->>'id')::uuid AND left_at IS NULL AND stack=1000 AND NOT is_sitting_out)<>3
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FINAL_CUSTODY_REFUSED' USING ERRCODE='55000';END IF;
 SELECT jsonb_build_object('reserve',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.spin_reserve_ledger r WHERE tournament_id=p_tournament_id),'journal',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE tournament_id=p_tournament_id AND category='spin_entry'),'draw',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.launch_id) FROM public.spin_draw_receipts d WHERE tournament_id=p_tournament_id)) INTO spin_after;
 IF spin_after IS DISTINCT FROM spin_before THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_SPIN_EFFECT_CHANGED' USING ERRCODE='P0404';END IF;
 INSERT INTO smarter_private.retirement_undealt_paid_entry_restorations
 (tournament_id,qualification_hash,transaction_id,instance_id,lease_generation,native_results)
 VALUES(p_tournament_id,md5(v::text),txid_current(),lease.instance_id,lease.lease_generation,results);
 RETURN jsonb_build_object('ok',true,'restored',restored,'native_results',results);
END;$function$;
ALTER FUNCTION smarter_private.continue_retired_undealt_paid_entry(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION smarter_private.continue_retired_undealt_paid_entry(uuid) FROM PUBLIC,anon,authenticated,service_role;
-- @financial
DO $original_paid_entry$
DECLARE r jsonb;
BEGIN
 IF md5(pg_get_functiondef('public.fn_assign_tournament_player_seat_atomic(uuid,uuid,uuid,integer)'::regprocedure))<>'260bc38e0c7965d7ef63b31d4c05cbd5'
 OR md5(pg_get_functiondef('public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer)'::regprocedure))<>'0fe132756ddf22122c91aa0d7fd323cd'
 OR md5(pg_get_functiondef('public.fn_spin_book_entry(uuid)'::regprocedure))<>'3e861cfde0bda50d16bc836a665bf4ab'
 OR md5(pg_get_functiondef('public.fn_sync_seat_first_player_count(uuid)'::regprocedure))<>'24b79979406ecba84423fd5da05c102f'
 OR md5(pg_get_functiondef('public.fn_lock_daily_mission_user(uuid)'::regprocedure))<>'0e9d2905374930bda4529a8febc6eff6'
 OR md5(pg_get_functiondef('public.fn_ca_guard_seat_creation()'::regprocedure))<>'34016ee7fb4957fe0d46dfb78c8fd5b7' THEN
  RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NATIVE_OWNER_CHANGED' USING ERRCODE='55000';END IF;
 r:=smarter_private.continue_retired_undealt_paid_entry('355408fa-bdac-40c9-aad9-e1396a32392f');
 IF r->>'ok'<>'true' OR r->>'restored'<>'2' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NOT_COMPLETED';END IF;
END;$original_paid_entry$;
-- @live-proof original_undealt_paid_entry_custody
SELECT EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations r JOIN smarter_private.retirement_undealt_paid_entry_qualification q USING(tournament_id) WHERE r.tournament_id='355408fa-bdac-40c9-aad9-e1396a32392f' AND r.qualification_hash=md5(q.expected::text) AND jsonb_array_length(r.native_results)=2 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.native_results) e WHERE e->>'ok' IS DISTINCT FROM 'true' OR (e->>'stack')::numeric<>1000))
 AND md5(pg_get_functiondef('smarter_private.continue_retired_undealt_paid_entry(uuid)'::regprocedure))='3af0c0b78ae87d8dd71fcdf2b64d8b5c'
 AND (SELECT count(*) FROM pg_trigger WHERE tgrelid IN ('smarter_private.retirement_undealt_paid_entry_qualification'::regclass,'smarter_private.retirement_undealt_paid_entry_restorations'::regclass) AND tgname IN ('qualification_immutable','restoration_immutable') AND tgenabled='O')=2
 AND (SELECT count(*) FROM pg_proc WHERE oid IN ('smarter_private.continue_retired_undealt_paid_entry(uuid)'::regprocedure,'smarter_private.retirement_undealt_paid_entry_immutable()'::regprocedure) AND pg_get_userbyid(proowner)='postgres')=2
 AND NOT has_function_privilege('anon','smarter_private.continue_retired_undealt_paid_entry(uuid)','EXECUTE')
 AND NOT has_function_privilege('authenticated','smarter_private.continue_retired_undealt_paid_entry(uuid)','EXECUTE')
 AND NOT has_function_privilege('service_role','smarter_private.continue_retired_undealt_paid_entry(uuid)','EXECUTE')
 AS installed;
COMMIT;
